def checkMirrorTree(n: int, e: int, A: list[int], B: list[int]) -> int:
    from collections import defaultdict

    def build_adj(edges):
        adj = defaultdict(list)
        for u, v in edges:
            adj[u].append(v)
        return adj

    adj_A = build_adj(zip(A[::2], A[1::2]))
    adj_B = build_adj(zip(B[::2], B[1::2]))

    if not adj_A and not adj_B:
        return 1

    root_A = None
    root_B = None
    for u in adj_A:
        if len(adj_A[u]) > 0:
            root_A = u
            break
    for u in adj_B:
        if len(adj_B[u]) > 0:
            root_B = u
            break
    if root_A != root_B:
        return 0

    def is_mirror(u, v, adj_A, adj_B):
        if len(adj_A[u]) != len(adj_B[v]):
            return False
